**Generating typed API client for frontend**

```typescript
// src/lib/api.ts
export interface Citation {
  doc_id: string;
  doc_title: string;
  page: number;
  snippet: string;
  score: number;
}

export interface QAResponse {
  query_id: string;
  answer: string;
  citations: Citation[];
  num_hits: number;
  latency_ms: number;
}

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8002";

async function fetchAPI<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${API_URL}${endpoint}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  if (!res.ok) throw new Error(`API Error: ${res.status}`);
  return res.json();
}

export const api = {
  health: () => fetchAPI<{status: string}>("/healthz"),
  getDocuments: (projectId: string) => 
    fetchAPI<Document[]>(`/api/documents?project_id=${projectId}`),
  ask: (query: string, projectId: string, k = 5) =>
    fetchAPI<QAResponse>("/api/ask", {
      method: "POST",
      body: JSON.stringify({ query, project_id: projectId, k }),
    }),
};
```

✓ TypeScript interfaces for all API types
✓ Typed API client with error handling
✓ Environment-based API URL

